  system: `workspace "T" {
    model {
        system "Order Platform" "Accepts orders"
    }
}`,
  container: `workspace "T" {
    model {
        container "Web Store" "order-web" "Web" "Browser-based storefront"
    }
}`,
  relationship: `workspace "T" {
    model {
        person "Customer" "Places orders"
        system "Order Platform" "Accepts orders"
        "Customer" -> "Order Platform" "Shops"
    }
}`,
  views_block: `workspace "T" {
    model {
        person "Customer" "Places orders"
        system "Order Platform" "Accepts orders"
    }
    views {
        systemContext "Order Platform" "ctx" {
            include *
            autoLayout
        }
    }
}`,
  theme: `workspace "T" {
    views {
        theme default
    }
}`,
  docs: `workspace "T" {
    !docs docs/
}`,
};
const results = {};
for (const [name, dsl] of Object.entries(tests)) {
  const r = await tools.structurizr.parse({ dsl }).then(
    (v) => ({ ok: true }),
    (e) => ({ ok: false, error: String(e) })
  );
  results[name] = r;
}
return results;

