  properties_block: `workspace "T" {
    properties {
        "structurizr.feature.dsl.documentation" = "true"
    }
    !docs docs/
}`,
  properties_block_alt: `workspace "T" {
    properties {
        structurizr.feature.dsl.documentation = true
    }
    !docs docs/
}`,
};
const results = {};
for (const [name, dsl] of Object.entries(tests)) {
  const v = await tools.structurizr.parse({ dsl }).then((x) => x, (e) => String(e));
  results[name] = typeof v === "string" ? { ok: false, error: v } : { ok: true, properties: v.properties };
}
return results;"}

input.code:
const model = `person "Customer" "Places and tracks orders"

softwareSystem "Order Platform" "Accepts orders and manages fulfilment" {
    container "Web Store" "Browser-based storefront" "Web"
    container "Order API" "REST API for order management" "Service"
    container "Order Database" "Stores order data" "PostgreSQL"
}

softwareSystem "Payment Gateway" "External payment processing"`;

const views = `theme default

styles {
    element "Person" {
        background "#0d7a8c"
    }
    element "Software System" {
        background "#1168bd"
    }
    element "Container" {
        background "#41c4a4"
    }
}`;

// Same as the on-disk workspace, minus the feature-flagged !docs line
const dsl = `workspace "Order Platform" {
    model {
${model}
    }
    views {
${views}
    }
}`;

const [parse, validate, inspect] = await Promise.allSettled([
  tools.structurizr.parse({ dsl }),
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);
const show = (r) => (r.status === "fulfilled" ? r.value : { error: String(r.reason) });
const p = show(parse);
return {
  parse_ok: typeof p !== "string",
  parse_summary: typeof p === "string" ? p : {
    name: p.name,
    people: (p.model.people || []).map((x) => x.name),
    systems: (p.model.softwareSystems || []).map((s) => ({ name: s.name, containers: (s.containers || []).map((c) => c.name) })),
    theme: p.views.configuration.themes,
    styles: (p.views.configuration.styles.elements || []).map((s) => s.tag),
  },
  validate: show(validate),
  inspect: show(inspect),
};

